const accents=["#c9ff3d","#c9ff3d","#c9ff3d","#ffd052","#ffd052","#ff6a3d","#4774ff","#4774ff","#ff6a3d","#ff9d69","#45c8ef","#d8a759","#b695ff","#ff8eb6","#58d4b0","#ff875f","#74a3ff","#b695ff","#ff554f","#c9ff3d"];
TASK_FAMILIES.forEach(f=>f.tasks.forEach((t,i)=>{t.id=`F${String(f.n).padStart(2,"0")}-T${String(i+1).padStart(2,"0")}`}));

const INSTANCE_VARIANTS=[
  {id:"I01",zh:"标准",en:""},{id:"I02",zh:"红色",en:"red"},{id:"I03",zh:"蓝色",en:"blue"},{id:"I04",zh:"黄色",en:"yellow"},
  {id:"I05",zh:"绿色",en:"green"},{id:"I06",zh:"橙色",en:"orange"},{id:"I07",zh:"黑色",en:"black"},{id:"I08",zh:"白色",en:"white"},
  {id:"I09",zh:"灰色",en:"gray"},{id:"I10",zh:"透明",en:"transparent"},{id:"I11",zh:"大号红色",en:"large red"},{id:"I12",zh:"小号红色",en:"small red"},
  {id:"I13",zh:"大号蓝色",en:"large blue"},{id:"I14",zh:"小号蓝色",en:"small blue"},{id:"I15",zh:"高型黄色",en:"tall yellow"},{id:"I16",zh:"矮型黄色",en:"short yellow"},
  {id:"I17",zh:"宽型绿色",en:"wide green"},{id:"I18",zh:"窄型绿色",en:"narrow green"},{id:"I19",zh:"条纹白色",en:"striped white"},{id:"I20",zh:"标签灰色",en:"labeled gray"}
];

const el={grid:document.querySelector("#familyGrid"),empty:document.querySelector("#emptyState"),search:document.querySelector("#searchInput"),scene:document.querySelector("#sceneFilter"),reset:document.querySelector("#resetBtn"),dialog:document.querySelector("#familyDialog"),dialogContent:document.querySelector("#dialogContent"),close:document.querySelector("#dialogClose"),sceneDialog:document.querySelector("#sceneDialog"),sceneDialogContent:document.querySelector("#sceneDialogContent"),sceneDialogClose:document.querySelector("#sceneDialogClose")};
SCENES.forEach(scene=>el.scene.insertAdjacentHTML("beforeend",`<option value="${scene}">${scene}</option>`));

function taskMatches(f,t){const q=el.search.value.trim().toLowerCase();const text=[f.zh,f.en,f.desc,...f.examples,t.name,t.scene,t.items,t.primaryObject,t.description,t.prompt].join(" ").toLowerCase();return(el.scene.value==="all"||t.scene===el.scene.value)&&(!q||text.includes(q));}
function visibleFamilies(){return TASK_FAMILIES.map(f=>({...f,matched:f.tasks.filter(t=>taskMatches(f,t))})).filter(f=>f.matched.length);}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function splitTaskItems(items){const parts=String(items).split(/[、，,]/).map(v=>v.trim()).filter(Boolean);return{primary:parts[0]||"目标物体",parts}}
function primaryObject(task){return task.primaryObject||splitTaskItems(task.items).primary}
function fixedReferences(task){if(task.fixedObjects)return task.fixedObjects;const {parts}=splitTaskItems(task.items),primary=primaryObject(task);let removed=false;const references=parts.filter(part=>{if(!removed&&(part.includes(primary)||primary.includes(part))){removed=true;return false}return true});if(!removed)references.shift();return references.join("、")||"无固定参照物"}
function instanceObject(task,variant){const primary=primaryObject(task);return variant.en?`${variant.zh}${primary}`:primary}
function escapeRegExp(value){return String(value).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}
function instancePrompt(task,variant){if(!variant.en)return task.prompt;const target=task.primaryObjectEn||"";if(target&&new RegExp(escapeRegExp(target),"i").test(task.prompt)){return task.prompt.replace(new RegExp(escapeRegExp(target),"i"),`${variant.en} ${target}`)}return`${task.prompt} using the ${variant.en} ${target||"object"}`}
function instanceOptions(task){return INSTANCE_VARIANTS.map((variant,index)=>`<option value="${index}">${variant.id} · ${escapeHtml(instanceObject(task,variant))}</option>`).join("")}
function successCriterion(){return"主交互物体达到任务描述中的最终状态，并稳定保持 1–2 秒。"}

function render(){const list=visibleFamilies();el.grid.innerHTML="";el.empty.hidden=list.length!==0;list.forEach(f=>{const card=document.createElement("article");card.className="family-card";card.style.setProperty("--accent",accents[f.n-1]);card.tabIndex=0;card.setAttribute("role","button");card.setAttribute("aria-label",`查看 ${f.zh} 的任务`);const examples=f.examples.map(escapeHtml).join(" <i>|</i> ");card.innerHTML=`<span class="family-number">FAMILY ${String(f.n).padStart(2,"0")}</span><h3>${escapeHtml(f.zh)}</h3><span class="family-en">${escapeHtml(f.en)}</span><p class="family-desc">${escapeHtml(f.desc)}</p><p class="example-label">E.G.</p><div class="family-examples dream-examples">${examples}</div><div class="family-bottom"><strong>${f.matched.length} / 10 TASKS</strong><b>查看任务 →</b></div>`;card.addEventListener("click",()=>openFamily(f));card.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openFamily(f)}});el.grid.appendChild(card)});}

function openFamily(f){
  const tasks=f.matched||f.tasks;
  const rows=tasks.map(t=>`<article class="task-row" data-task-id="${t.id}"><div class="task-row-index">${t.id}</div><div class="task-main"><div class="task-title-line"><h3>${escapeHtml(t.name)}</h3><span>20 个单物体实例</span></div><div class="task-badges"><span class="badge">${escapeHtml(f.zh)}</span><span class="badge">${escapeHtml(t.scene)}</span></div><div class="task-definition"><div class="detail"><small>任务目标</small><p>${escapeHtml(t.description)}</p></div><div class="detail"><small>成功条件</small><p>${escapeHtml(successCriterion(t))}</p></div><div class="detail instance-detail"><small>主交互物体 / 物品实例</small><label class="instance-select"><select aria-label="选择 ${escapeHtml(t.name)} 的主交互物体实例">${instanceOptions(t)}</select><i>⌄</i></label><p class="instance-object">${escapeHtml(instanceObject(t,INSTANCE_VARIANTS[0]))}</p></div><div class="detail reference-detail"><small>固定参照物 / 环境道具</small><p>${escapeHtml(fixedReferences(t))}</p><em>仅用于定义目标位置或场景条件，不参与实例切换。</em></div></div><div class="prompt"><strong>语言指令</strong><q>${escapeHtml(t.prompt)}</q></div><p class="episode-rule">每条 Episode 只操作当前选中的主交互物体；固定参照物保持不动。任务行为保持一致，主交互物体的初始位置与目标位置在规定区域内合理随机化。</p></div></article>`).join("");
  el.dialogContent.innerHTML=`<div class="dialog-body"><span class="dialog-kicker">FAMILY ${String(f.n).padStart(2,"0")} · ${tasks.length} TASKS</span><h2>${escapeHtml(f.zh)}</h2><p class="dialog-summary"><strong>${escapeHtml(f.en)}</strong> — ${escapeHtml(f.desc)}</p><div class="dialog-eg"><strong>E.G.</strong>${f.examples.map(escapeHtml).join(" <i>|</i> ")}</div><div class="instance-policy"><strong>SINGLE-OBJECT POLICY</strong><span>每个原子任务只设置 1 个主交互物体，并配置 20 个物品实例；其他物体仅作为固定参照。每个实例采集 1 条有效 Episode，切换实例后仅更新主交互物体与英文 instruction。</span></div><div class="task-list">${rows}</div></div>`;
  el.dialogContent.querySelectorAll(".task-row").forEach((row,index)=>{const task=tasks[index],select=row.querySelector(".instance-select select"),object=row.querySelector(".instance-object"),prompt=row.querySelector(".prompt q");select.addEventListener("change",()=>{const variant=INSTANCE_VARIANTS[Number(select.value)];object.textContent=instanceObject(task,variant);prompt.textContent=instancePrompt(task,variant)})});
  el.dialog.showModal();document.body.classList.add("no-scroll");
}
function closeDialog(){el.dialog.close();document.body.classList.remove("no-scroll")}
function sceneStorageKey(sceneName){return `unitree-scene-material-links:${sceneName}`}
function readSceneMaterials(sceneName,defaults){try{const saved=JSON.parse(localStorage.getItem(sceneStorageKey(sceneName))||"null");if(Array.isArray(saved))return saved;if(saved&&typeof saved==="object")return defaults.map(name=>({name,url:saved[name]||""}));return defaults.map(name=>({name,url:""}))}catch{return defaults.map(name=>({name,url:""}))}}
function writeSceneMaterials(sceneName,materials){try{localStorage.setItem(sceneStorageKey(sceneName),JSON.stringify(materials));return true}catch{return false}}
function safeMaterialUrl(value){const url=String(value||"").trim();return /^https?:\/\//i.test(url)?url:"#"}
function sceneText(card,selector,label){return card.querySelector(selector).textContent.trim().replace(new RegExp(`^${label}`),"").trim().replace(/。$/,"")}
function materialRow(material,i){const raw=String(material.url||"").trim(),url=safeMaterialUrl(raw),linked=url!=="#";return `<tr><td><div class="material-name-cell"><span class="material-index">${String(i+1).padStart(2,"0")}</span><input class="material-name" value="${escapeHtml(material.name||"")}" placeholder="填写物料名称" aria-label="物料名称"></div></td><td><div class="material-link-cell"><input class="material-url${linked?" is-linked":""}" type="url" inputmode="url" value="${escapeHtml(raw)}" placeholder="https://…" aria-label="物料链接"><a class="material-link${linked?" is-visible":""}" href="${escapeHtml(url)}" target="_blank" rel="noreferrer">${escapeHtml(raw)}</a><button type="button" class="material-link-edit${linked?" is-visible":""}">修改</button></div></td><td><button type="button" class="material-delete" aria-label="删除该物料">删除</button></td></tr>`}
function reindexMaterialRows(tbody){[...tbody.rows].forEach((row,i)=>row.querySelector(".material-index").textContent=String(i+1).padStart(2,"0"))}
function openSceneDetail(card,index){
  const sceneName=card.querySelector("h3").textContent.trim();
  const layout=sceneText(card,".scene-layout","空间特征");
  const items=(card.dataset.materials||"").split(/[、，,]/).map(v=>v.trim()).filter(Boolean);
  const materials=readSceneMaterials(sceneName,items);
  el.sceneDialogContent.innerHTML=`<div class="dialog-body scene-dialog-body"><span class="dialog-kicker">SCENE ${String(index+1).padStart(2,"0")} · MATERIAL REGISTER</span><h2>${escapeHtml(sceneName)}</h2><div class="scene-layout-detail"><small>空间特征</small><p>${escapeHtml(layout)}</p></div><div class="material-table-wrap"><table class="material-table"><thead><tr><th>物料名称</th><th>物料链接</th><th>操作</th></tr></thead><tbody>${materials.map(materialRow).join("")}</tbody></table></div><button type="button" class="material-add">＋ 添加物料</button><div class="material-actions"><p>物料及链接仅保存在当前浏览器，不会上传或公开。</p><span class="material-save-status" aria-live="polite"></span><button type="button" class="material-save">保存物料清单</button></div></div>`;
  const tbody=el.sceneDialogContent.querySelector(".material-table tbody");
  const status=el.sceneDialogContent.querySelector(".material-save-status");
  const activateLink=input=>{const cell=input.closest(".material-link-cell"),link=cell.querySelector(".material-link"),edit=cell.querySelector(".material-link-edit"),raw=input.value.trim(),url=safeMaterialUrl(raw);if(url==="#")return;link.href=url;link.textContent=raw;input.classList.add("is-linked");link.classList.add("is-visible");edit.classList.add("is-visible")};
  tbody.addEventListener("input",()=>{status.textContent=""});
  tbody.addEventListener("focusout",e=>{if(e.target.classList.contains("material-url"))activateLink(e.target)});
  tbody.addEventListener("keydown",e=>{if(e.target.classList.contains("material-url")&&e.key==="Enter"){e.preventDefault();activateLink(e.target)}});
  tbody.addEventListener("click",e=>{const edit=e.target.closest(".material-link-edit");if(edit){const cell=edit.closest(".material-link-cell"),input=cell.querySelector(".material-url");input.classList.remove("is-linked");cell.querySelector(".material-link").classList.remove("is-visible");edit.classList.remove("is-visible");input.focus();input.select();return}const button=e.target.closest(".material-delete");if(button){button.closest("tr").remove();reindexMaterialRows(tbody);status.textContent=""}});
  el.sceneDialogContent.querySelector(".material-add").addEventListener("click",()=>{tbody.insertAdjacentHTML("beforeend",materialRow({name:"",url:""},tbody.rows.length));tbody.lastElementChild.querySelector(".material-name").focus();status.textContent=""});
  el.sceneDialogContent.querySelector(".material-save").addEventListener("click",()=>{const values=[...tbody.rows].map(row=>({name:row.querySelector(".material-name").value.trim(),url:row.querySelector(".material-url").value.trim()})).filter(item=>item.name||item.url);const ok=writeSceneMaterials(sceneName,values);status.textContent=ok?"已保存":"浏览器未允许本地保存"});
  el.sceneDialog.showModal();document.body.classList.add("no-scroll");
}
function closeSceneDialog(){el.sceneDialog.close();document.body.classList.remove("no-scroll")}
document.querySelectorAll(".scene-card").forEach((card,index)=>{const trigger=document.createElement("button");trigger.type="button";trigger.className="scene-detail-trigger";trigger.innerHTML="<span>物料配置</span><b>→</b>";trigger.addEventListener("click",()=>openSceneDetail(card,index));card.appendChild(trigger)});
function reset(){el.search.value="";el.scene.value="all";render()}
render();[el.search,el.scene].forEach(x=>x.addEventListener(x===el.search?"input":"change",render));el.reset.addEventListener("click",reset);el.close.addEventListener("click",closeDialog);el.dialog.addEventListener("click",e=>{if(e.target===el.dialog)closeDialog()});el.sceneDialogClose.addEventListener("click",closeSceneDialog);el.sceneDialog.addEventListener("click",e=>{if(e.target===el.sceneDialog)closeSceneDialog()});document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(el.sceneDialog.open)closeSceneDialog();else if(el.dialog.open)closeDialog()}});
